    struct Message {
        address Sender;
        uint Time;
        uint Val;
        string Data;
    }

    Message[] public History;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        Message memory newMsg = Message(_adr, block.timestamp, _val, _data);
        History.push(newMsg);
    }
